1	// The `fleet` signal reader (per-project-scheduling DESIGN §3.3) — the members
2	// aggregate the CANON repo's fleet-scoped tasks (growth-promote,
3	// growth-discover-packs) decide from. A consumer cannot
4	// declare `fleet`; only the canon repo's scheduler builds it, over the fleet PAT
5	// (`FLEET_GITHUB_TOKEN` — the census's existing credential, the one token that
6	// can enumerate every repo the owner owns; the Action's default GITHUB_TOKEN sees
7	// only this repo). queue/signals.mjs invokes this ONLY when the picked task declares `fleet`, so
8	// an ordinary night pays nothing for the fleet enumeration.
9	//
10	// Pure over an injected `fleetGh` (the same `gh(path) -> { status, json }` shape
11	// the other collectors take), so the whole reader tests against a fake `gh` with
12	// no live GitHub — exactly like signals/index.mjs. The one place the real
13	// FLEET_GITHUB_TOKEN is read is `makeFleetGh`, at the I/O edge.
14	//
15	// This deliberately ports the retired central planner's per-member probes (the
16	// `fleetMembers` bundle the old central planner stamped on the home repo) into
17	// the per-repo scheduler, adapted for the `local/packs` rename (both roots
18	// accepted through the migration) and carrying each member's provenance stamp so
19	// the retire guard can read per-repo apply evidence.
20	
21	import { makeGh } from './gh.mjs';
22	import { packEntryId } from '../../../engine/pack_loader/pack-registry.mjs';
23	// Local-pack roots, canonical first — a window commit touching either is a local
24	// -pack change (promote's trigger). Both are live until the Phase 4 cleanup drops
25	// the legacy dual root. One definition, shared with the per-repo probes.
26	import { LOCAL_PACK_ROOT } from './local.mjs';
27	import { SETTINGS_FILES } from '../../../engine/settings-file.mjs';
28	// The one definition of dormancy, shared with every other fleet reader: a second
29	// notion of it would sweep exactly the members that had already opted out.
30	import { isDormant } from '../../../engine/checks/helpers/repo-context.mjs';
31	
32	async function paged(gh, path) {
33	  const out = [];
34	  for (let page = 1; ; page += 1) {
35	    const sep = path.includes('?') ? '&' : '?';
36	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
37	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
38	    out.push(...json);
39	    if (json.length < 100) break;
40	  }
41	  return out;
42	}
43	
44	// A repo mounts Claudinite iff it carries the tracked declaration file — the one
45	// membership signal every member has whatever its mount shape (the same test the
46	// census's isCovered uses: activePacks are read from it, so a mount marker with
47	// no declaration is a half-adoption that must classify as uncovered).
48	function parseChecks(contentB64) {
49	  try { return JSON.parse(Buffer.from(contentB64, 'base64').toString('utf8')); }
50	  catch { return null; }
51	}
52	
53	// The member's declared packs (BARE ids, either declaration form), each entry's
54	// config (id -> config, so home-only gates honor per-pack settings like the
55	// growth promote opt-out), the per-repo scheduling cutover marker, and the
56	// vendored-mount provenance stamp (retire's per-repo apply evidence).
57	function readDeclaration(checks) {
58	  const entries = Array.isArray(checks?.packs) ? checks.packs : [];
59	  const activePacks = entries.map((e) => packEntryId(e)).filter((id) => typeof id === 'string');
60	  const packConfigs = {};
61	  for (const e of entries) {
62	    if (e && typeof e === 'object' && typeof e.id === 'string' && e.config !== undefined) {
63	      packConfigs[packEntryId(e)] = e.config;
64	    }
65	  }
66	  const schedulesItself = checks?.taskScheduler !== undefined && checks?.taskScheduler !== null;
67	  const stamp = checks?.claudinite ?? null;
68	  return {
69	    dormant: isDormant(checks),
70	    activePacks,
71	    packConfigs,
72	    schedulesItself,
73	    stamp: stamp ? { updated: stamp.updated ?? null, ref: stamp.ref ?? null } : null,
74	  };
75	}
76	
77	// Did a default-branch commit in the window touch this member's local packs (the
78	// real promote trigger — a member that changed product code but not its local
79	// packs has nothing to lift up)? Scans only the window's commits (a handful) and
80	// stops at the first hit; a commit whose files can't be read contributes nothing.
81	async function localPacksChangedInWindow(gh, fullName, defaultBranch, sinceIso) {
82	  const list = await paged(gh, `/repos/${fullName}/commits?sha=${encodeURIComponent(defaultBranch)}&since=${sinceIso}`);
83	  for (const c of list) {
84	    if (!c?.sha) continue;
85	    const detail = await gh(`/repos/${fullName}/commits/${c.sha}`);
86	    const files = detail.status === 200 ? (detail.json?.files ?? []) : [];
87	    if (files.some((f) => typeof f.filename === 'string' && f.filename.startsWith(LOCAL_PACK_ROOT))) return true;
88	  }
89	  return false;
90	}
91	
92	// Build one member's record from its declaration plus the local-pack window scan.
93	// `sinceIso` bounds the window. Whether the member HAS local packs is not probed:
94	// adoption seeds `.claudinite/local/packs/<repo>/` and the nightly deliberately
95	// never re-seeds or removes it, so the answer was yes for every member and the
96	// probe was one contents read per member per collection. An undeclared repo is
97	// still skipped — it is not a member anything plans for.
98	async function buildMember(gh, repo, sinceIso) {
99	  const fullName = repo.full_name;
100	  const defaultBranch = repo.default_branch || 'main';
101	  const decl = readDeclaration(repo.checks);
102	  const localChanged = decl.activePacks.length
103	    ? await localPacksChangedInWindow(gh, fullName, defaultBranch, sinceIso)
104	    : false;
105	  return {
106	    repo: fullName,
107	    defaultBranch,
108	    activePacks: decl.activePacks,
109	    packConfigs: decl.packConfigs,
110	    localPacksChanged: localChanged,
111	    schedulesItself: decl.schedulesItself,
112	    stamp: decl.stamp,
113	  };
114	}
115	
116	// Read the fleet aggregate: every COVERED member the owner owns (excluding the
117	// canon repo itself, forks, archived repos, and members declaring themselves
118	// dormant), each with its declaration +
119	// local-pack window probe. Pure over `fleetGh`. Returns `{ owner, members, error }`;
120	// `error` is set (and `members` empty) when enumeration itself failed or returned
121	// nothing — a fleet task's precondition treats an errored/empty fleet as "no work
122	// I can prove", never as "the fleet is empty" (the census's own refuse-on-empty
123	// rule: an empty enumeration is a wrong-token/scope symptom, not consent).
124	export async function readFleet(fleetGh, { owner, canonRepo, sinceIso }) {
125	  const ownerLc = String(owner).toLowerCase();
126	  const mine = await paged(fleetGh, '/user/repos?affiliation=owner');
127	  const owned = mine.filter((r) => r?.owner?.login?.toLowerCase() === ownerLc);
128	  if (owned.length === 0) {
129	    return { owner: ownerLc, members: [], error: `enumeration returned no repos owned by ${ownerLc} — wrong token user or scope` };
130	  }
131	  const members = [];
132	  for (const r of owned.sort((a, b) => a.name.localeCompare(b.name))) {
133	    const fullName = r.full_name;
134	    if (fullName.toLowerCase() === String(canonRepo).toLowerCase()) continue; // the canon doesn't mount itself
135	    if (r.archived || r.fork) continue;
136	    // Either settings-file name: a member the #1252 rename record has not reached
137	    // still carries the old one, and reading only the new name would drop it from
138	    // the fleet silently — as an uncovered repo, which is a plan for nothing.
139	    let res = null;
140	    for (const name of SETTINGS_FILES) {
141	      res = await fleetGh(`/repos/${fullName}/contents/${name}`);
142	      if (res.status === 200 && res.json?.content) break;
143	      res = null;
144	    }
145	    if (!res) continue; // uncovered — no tracked declaration
146	    const checks = parseChecks(res.json.content);
147	    if (!checks) continue; // unparsable declaration → not a member we can plan for
148	    // Declared dormant → out of the recurring work, which is the only thing this
149	    // signal feeds. Skipped HERE rather than in each consuming precondition, so a
150	    // dormant member costs neither an opus sweep nor the per-member probes below.
151	    if (isDormant(checks)) continue;
152	    members.push(await buildMember(fleetGh, { full_name: fullName, default_branch: r.default_branch, checks }, sinceIso));
153	  }
154	  return { owner: ownerLc, members };
155	}
156	
157	// The I/O edge: build a fleet `gh` from FLEET_GITHUB_TOKEN, or null when the
158	// secret isn't set (a consumer, or the canon before the secret is provisioned) —
159	// the collector then leaves ctx.fleet null and returns null, so the
160	// fleet tasks' preconditions skip rather than crash.
161	export function makeFleetGh(env = process.env) {
162	  const token = env.FLEET_GITHUB_TOKEN;
163	  if (!token) return null;
164	  return makeGh({ token });
165	}
166

