export function shelfPacks(git, ref) {
  const paths = git(['ls-tree', '--name-only', '-r', ref, `${SHELF}/`]).split('\n');
  return paths.map((p) => /^packs\/([^/]+)\/pack\.mjs$/.exec(p)?.[1]).filter(Boolean).sort();
